// Stateless Streamable HTTP serving for /mcp. ADR 0020.
//
// Each request gets its own McpServer and its own sessionless transport
// (createLegacyMcpHandler with no sessionIdGenerator and no storage), so no
// Durable Object is created, nothing is persisted, and nothing is left behind
// to clean up. The SDK v1 server is kept on purpose: it is what the published
// tool schemas are generated by (ADR 0009, mcp-schema-contract.test.ts), so
// the wire contract is unchanged.
//
// What a session would have bought, and why none of it is used here:
//   - server-to-client requests (elicitation, sampling, roots): no tool asks;
//   - a standalone GET SSE stream for server-initiated notifications: nothing
//     is ever pushed (no list changes, no subscriptions, no logging) — hence
//     the 405 below, which the spec allows;
//   - Last-Event-ID resumability: replaced by the transport's SSE keep-alive
//     frames on the response stream, which hold long calls
//     (kagi_research_wait_for_run, up to 300 s) open.

import { createLegacyMcpHandler } from "agents/mcp";
import type { Env } from "../env.js";
import { createKagiMcpServer } from "../mcp.js";

export const MCP_ROUTE = "/mcp";

export async function serveMcp(request: Request, env: Env, ctx: ExecutionContext): Promise<Response> {
  if (request.method === "GET" && new URL(request.url).pathname === MCP_ROUTE) {
    // No body: SDK clients treat a 405 here as "no stream offered" and drop
    // the response unread, so a body would only be written into a closed
    // connection.
    return new Response(null, { status: 405, headers: { Allow: "POST, DELETE" } });
  }
  const server = createKagiMcpServer(env, (p) => ctx.waitUntil(p));
  return createLegacyMcpHandler(server, { route: MCP_ROUTE })(request, env, ctx);
}
